window.AUTH=window.AUTH||{};window.AUTH["24-1016"]={"d":"24-1016","id":"2026/24-1016","n":"RiseandShine Corporation v. PepsiCo, Inc.","briefs":[{"k":"petitioner","label":"Brief of petitioner RiseandShine Corporation, dba Rise Brewing","date":"2026-09-08","url":"https://www.supremecourt.gov/DocketPDF/24/24-1016/423497/20260908233710240_24-1016_Brief.pdf","side":"pet","n":56},{"k":"united-states","label":"Brief amicus curiae of United States supporting vacatur","date":"2026-09-15","url":"https://www.supremecourt.gov/DocketPDF/24/24-1016/424405/20260917111153556_24-1016tsacUnitedStates.pdf","side":"pet","n":44},{"k":"respondent","label":"Brief of respondent PepsiCo, Inc.","date":"2026-11-04","url":"https://www.supremecourt.gov/DocketPDF/24/24-1016/431887/20261104210121988_PepsiCo%20Brief%20for%20Respondent.pdf","side":"res","n":90}],"opinion":null,"tr":false,"items":[{"t":"case","label":"A & H Sportswear, Inc. v. Victoria’s Secret Stores, Inc.","cite":"237 F.3d 198","y":2000,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/237/198/","sum":"Noting that “the particular category of ‘distinctiveness’ into which a mark falls … is not the only measure of conceptual strength”.","sumSrc":"brief:2","by":{"0":"28","2":"8, 35"}},{"t":"case","label":"A.J. Canfield Co. v. Honickman","cite":"808 F.2d 291","y":1986,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.2d/808/291/","by":{"0":"28"}},{"t":"case","label":"Abercrombie & Fitch Co. v. Hunting World, Inc.","cite":"537 F.2d 4","y":1976,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.2d/537/4/","by":{"0":"5","1":"5, 23","2":"5"}},{"t":"case","label":"Anheuser-Busch, Inc. v. Stroh Brewery Co.","cite":"750 F.2d 631","y":1984,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.2d/750/631/","by":{"0":"29"}},{"t":"case","label":"B&B Hardware, Inc. v. Hargis Indus., Inc.","cite":"575 U.S. 138","y":2015,"id":"2014/13-352","sc":1,"sum":"The Court held that a decision on an issue by an administrative agency can preclude re-litigation of that issue in federal court.","sumSrc":"Oyez","by":{"0":"5-6","1":"3, 4","2":"4, 7"}},{"t":"case","label":"Bayer Co. v. United Drug Co.","cite":"272 F. 505","y":1921,"court":"S.D.N.Y.","url":"https://www.courtlistener.com/c/F./272/505/","sum":"Explaining that “aspirin” had become generic and that the “single question” in determining that the mark lacked protectable strength was one “of fact: What do the buyers understand by the word for whose use the parties are contending?”.","sumSrc":"brief:0","by":{"0":"10, 15, 16"}},{"t":"case","label":"Blinded Veterans Ass’n v. Blinded Am. Veterans Found.","cite":"872 F.2d 1035","y":1989,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.2d/872/1035/","by":{"0":"31"}},{"t":"case","label":"Champions Golf Club, Inc. v. The Champions Golf Club","cite":"78 F.3d 1111","court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/78/1111/","by":{"0":"6"}},{"t":"case","label":"Cited Authorities Page City of Monterey v. Del Monte Dunes at Monterey, Ltd.","cite":"526 U.S. 687","y":1999,"id":"1998/97-1235","sc":1,"sum":"The Court held, in an opinion authored by Justice Anthony M. Kennedy, that property owners who file a Section 1983 civil rights suit seeking compensation for an alleged taking of their property can have a jury trial in some circumstances. \"[T]he disputed questions were whether the government had denied a constitutional right outside the bounds of its authority, and, if so, the extent of any resulting damages.\" Justice Kennedy then added: \"These were questions for the jury.\".","sumSrc":"Oyez","by":{"0":"35","2":"50"}},{"t":"case","label":"City of New York by and through FDNY v. Henriquez","cite":"98 F.4th 402","y":2024,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.4th/98/402/","by":{"0":"9, 31"}},{"t":"case","label":"Comm’r v. Duberstein","cite":"363 U.S. 278","y":1960,"id":"1959/376","sc":1,"sum":"On the record in this case, it cannot be said COMMISSIONER v. DUBERSTEIN..278","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"25"}},{"t":"case","label":"Dairy Queen, Inc. v. Wood","cite":"369 U.S. 469","y":1962,"id":"1961/244","sc":1,"sum":"The District Judge erred in refusing petitioner's.demand for a trial by jury of the factual issues related to the question whether there had been a breach of contract or a trademark infringement, and the Court of Appeals should have corrected that error by granting the petition for mandamus.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"26","2":"50"}},{"t":"case","label":"Dayton Bd. of Educ. v. Brinkman","cite":"443 U.S. 526","y":1979,"id":"1978/78-627","sc":1,"sum":"A number of students in the Dayton, Ohio, school system, through their parents, brought this action in District Court in 1972, alleging that the Dayton Board of Education, the State Board of Education, and various local and state officials were operating a racially segregated school system in violation of the Equal Protection Clause of the Fourteenth Amendment. After protracted litigation at both the trial and …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"25"}},{"t":"case","label":"Dimick v. Schiedt","cite":"293 U.S. 474","y":1935,"id":"scdb/1934-155","sc":1,"sum":"1. Under the Seventh Amendment, a federal court, finding a verdict inadequate, is without power to add to it by refusing to grant the plaintiff a new trial if the defendant will accept an increase which the court deems sufficient. So held in an action for personal injuries due to negligence.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"35"}},{"t":"case","label":"Donchez v. Coors Brewing Co.","cite":"392 F.3d 1211","y":2004,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/392/1211/","by":{"0":"30"}},{"t":"case","label":"DuoProSS Meditech Corp. v. Inviro Med. Devices, Ltd.","cite":"695 F.3d 1247","y":2012,"court":"Fed. Cir.","url":"https://www.courtlistener.com/c/F.3d/695/1247/","by":{"0":"31"}},{"t":"case","label":"Equine Techs., Inc. v. Equitechnology, Inc.","cite":"68 F.3d 542","y":1995,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.3d/68/542/","by":{"0":"28"}},{"t":"case","label":"Cited Authorities Page Fortune Dynamic, Inc. v. Victoria’s Secret Stores Brand Mgmt., Inc.","cite":"618 F.3d 1025","y":2010,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/618/1025/","by":{"0":"30"}},{"t":"case","label":"Forum Corp. of N. Am. v. Forum, Ltd.","cite":"903 F.2d 434","y":1990,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.2d/903/434/","by":{"0":"29"}},{"t":"case","label":"G. Heileman Brewing Co. v. Anheuser-Busch Inc.","cite":"873 F.2d 985","y":1989,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.2d/873/985/","by":{"0":"29"}},{"t":"case","label":"Hanover Star Milling Co. v. Metcalf","cite":"240 U.S. 403","y":1916,"id":"scdb/1915-112","sc":1,"sum":"Two District Courts in different circuits having'granted temporary -injunctions, and both Circuit Courts of Appeals having reversed upon grounds that went to the merits and differed upon fundamental questionsaffecting the same trade-mark,' writs of.certiorari.were allowed by this court before final decrees, notwithstanding the general rule to the contrary.","sumSrc":"Headnote (U.S. Reports)","by":{"0":"5"}},{"t":"case","label":"Hana Financial, Inc. v. Hana Bank","cite":"574 U.S. 418","y":2015,"id":"2014/13-1211","sc":1,"sum":"The Court held that \"trademark tacking\" is a mixed question of fact and law to be decided by the jury.","sumSrc":"Oyez","by":{"0":"11, 12, 13, 21, 22, 23, 24, 32, 34","1":"2, 3, 13, 14, 18, 19, 22, 25, 28, 31","2":"38-39, 42-45, 52"}},{"t":"case","label":"Cited Authorities Page Jack Daniel’s Props., Inc. v. VIP Prods. LLC","cite":"599 U.S. 140","y":2023,"id":"2022/22-148","sc":1,"sum":"When a defendant in a trademark suit uses the mark as a designation of source for its own goods or services—i.e., as a trademark—the threshold Rogers test for trademark infringement claims challenging so-called expressive works, see Rogers v. Grimaldi, 875 F. 2d 994, does not apply, and the Lanham Act’s exclusion from liability for “[a]ny noncommerical use of a mark,” §1125(c)(3)(C), does not shield parody, criticism, or commentary from a claim of trademark dilution.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"5","1":"3","2":"5-7, 25-26, 33"}},{"t":"case","label":"James Burrough Ltd. v. Sign of Beefeater, Inc.","cite":"540 F.2d 266","y":1976,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.2d/540/266/","by":{"0":"6"}},{"t":"case","label":"KP Permanent Make-Up, Inc. v. Lasting Impression I, Inc.","cite":"543 U.S. 111","y":2004,"id":"2004/03-409","sc":1,"sum":"The Court held that a party raising the classic defense of fair use did not need to negate any likelihood that the practice under question would confuse consumers about the origin of the goods. The Court interpreted federal trademark law as placing the burden of showing likelihood of confusion on the party charging infringement.","sumSrc":"Oyez","by":{"0":"5","1":"2, 6, 20, 28","2":"25"}},{"t":"case","label":"Lane Cap. Mgmt. v. Lane Cap. Mgmt.","cite":"192 F.3d 337","y":1999,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/192/337/","by":{"0":"12-13, 30, 31"}},{"t":"case","label":"Magic Wand, Inc. v. RDB, Inc.","cite":"940 F.2d 638","y":1991,"court":"Fed. Cir.","url":"https://www.courtlistener.com/c/F.2d/940/638/","sum":"Explaining that the statute “codified the time-honored test for genericness articulated by Judge Learned Hand in Bayer Co. v. United Drug Co., 272 F. 505 (S.D.N.Y. 1921): ‘What do the buyers understand by the word for whose use the parties are contending?’”.","sumSrc":"brief:0","by":{"0":"16"}},{"t":"case","label":"Maker’s Mark Distillery, Inc. v. Diageo N. Am., Inc.","cite":"679 F.3d 410","y":2012,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/679/410/","by":{"0":"6"}},{"t":"case","label":"Markman v. Westview Instruments, Inc.","cite":"517 U.S. 370","y":1996,"id":"1995/95-26","sc":1,"sum":"Authored by Justice David H. Souter, the Court held that the construction of a patent, including terms of art within its claim, is exclusively within the province of the court. Justice Souter wrote that \"judges, not juries, are the better suited to find the acquired meaning of patent terms.\".","sumSrc":"Oyez","by":{"0":"22, 23","2":"24-25, 27-29"}},{"t":"case","label":"Mishawaka Rubber & Woolen Mfg. Co. v. S.S. Kresge Co.","cite":"316 U.S. 203","y":1942,"id":"scdb/1941-095","sc":1,"sum":"In order that he may recover profits under § 19 of the Trademark Act, the trademark owner is not required to prove that the purchasers of goods bearing the infringing mark were induced by it to believe that the goods were the goods of the trademark owner and purchased for that reason, and that they would otherwise have bought of him. P. 206. 119 F. 2d 316, reversed. CERTIORARI, 314 U. S. 603, to review the …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"19"}},{"t":"case","label":"Pierce v. Underwood","cite":"487 U.S. 552","y":1988,"id":"1987/86-1512","sc":1,"sum":"One of petitioner's predecessors as Secretary of Housing and Urban Development decided not to implement an \"operating subsidy\" program authorized by federal statute, which was intended to provide payments to owners of Government-subsidized apartment buildings to offset rising utility expenses and property taxes. Various plaintiffs, including respondent members of a nationwide class of Government-subsidized housing …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"24"}},{"t":"case","label":"Cited Authorities Page Pizzeria Uno Corp. v. Temple","cite":"747 F.2d 1522","y":1984,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.2d/747/1522/","by":{"0":"28"}},{"t":"case","label":"Polaroid Corp. v. Polarad Electronics Corp.","cite":"287 F.2d 492","y":1961,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.2d/287/492/","by":{"0":"7","1":"6, 21","2":"7"}},{"t":"case","label":"Pullman-Standard v. Swint","cite":"456 U.S. 273","y":1982,"id":"1981/80-1190","sc":1,"sum":"The Court of Appeals erred in the course of its review of the District Court's judgment.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"12, 25"}},{"t":"case","label":"Railroad Co. v. Stout","cite":"84 U.S. 657","y":1873,"id":"scdb/1873-101","sc":1,"sum":"Henry Stout, a child six year's of age and living-with his parents, sued, by his next friend, the Sioux City and Pacific Railroad Company, in the court below, to recover damages for an injury sustained upon a turntable belonging to the said company. The turntable was in an open space, about eighty rods from the company’s depot, in a hamlet or settlement of one hundred to one hundred and fifty persons. Near the …","sumSrc":"Headnote (U.S. Reports)","by":{"0":"25"}},{"t":"case","label":"Singleton v. Bolton","cite":"3 Douglas Reports 293","y":1783,"url":"https://www.courtlistener.com/c/Douglas%20Reports/3/293/","by":{"0":"26"}},{"t":"case","label":"Tumblebus Inc. v. Cranmer","cite":"399 F.3d 754","y":2005,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/399/754/","by":{"0":"29"}},{"t":"case","label":"Two Pesos, Inc. v. Taco Cabana, Inc.","cite":"505 U.S. 763","y":1992,"id":"1991/91-971","sc":1,"sum":"The Supreme Court held that trade dress can be protected under the Lanham Act based on inherent distinctiveness even if there is no proof of a secondary meaning. Recovery is usually available for trademark infringement without a secondary meaning, and there is no persuasive reason for treating trade dress differently from other types of trademark.","sumSrc":"Oyez","by":{"0":"5, 15","1":"5","2":"5-6, 33-34"}},{"t":"case","label":"U.S. Bank N.A. v. Village at Lakeridge, LLC","cite":"583 U.S. 387","y":2018,"id":"2017/15-1509","sc":1,"sum":"The Court held that a designation of non-statutory insider status is reviewable under the standard of clear error because the \"mixed question\" of law and fact at issue is primarily factual.","sumSrc":"Oyez","by":{"0":"12, 24","1":"14, 16, 17, 26-28","2":"22-23, 30"}},{"t":"case","label":"Union Carbide Corp. v. Ever-Ready, Inc.","cite":"531 F.2d 366","y":1976,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.2d/531/366/","by":{"0":"28"}},{"t":"case","label":"Cited Authorities Page Union Nat. Bank of Texas, Laredo, Tex. v. Union Nat. Bank of Texas, Austin, Tex.","cite":"909 F.2d 839","y":1990,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.2d/909/839/","by":{"0":"29"}},{"t":"case","label":"United States Patent & Trademark Office v. Booking.com B.V.","cite":"591 U.S. 549","y":2020,"url":"https://supreme.justia.com/cases/federal/us/591/549/","sc":1,"by":{"0":"5, 11, 13, 14, 15","1":"4, 5, 13, 19"}},{"t":"case","label":"United States v. Yellow Cab Co.","cite":"338 U.S. 338","y":1949,"id":"scdb/1949-016","sc":1,"sum":"Judgment affirmed.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"25"}},{"t":"case","label":"Wedgwood Homes, Inc. v. Lund","cite":"659 P.2d 377","y":1983,"court":"Or.","url":"https://www.courtlistener.com/c/P.2d/659/377/","by":{"0":"20"}},{"t":"case","label":"Welding Servs., Inc. v. Forman","cite":"509 F.3d 1351","y":2007,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/509/1351/","sum":"Concluding that “Welding Services” mark “is generic”.","sumSrc":"brief:2","by":{"0":"30","2":"49"}},{"t":"case","label":"Xtreme Lashes, LLC v. Xtended Beauty, Inc.","cite":"576 F.3d 221","y":2009,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/576/221/","by":{"0":"28"}},{"t":"case","label":"Zatarains, Inc. v. Oak Grove Smokehouse, Inc.","cite":"698 F.2d 786","y":1983,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.2d/698/786/","by":{"0":"28-29"}},{"t":"const","label":"Amendment VII","clauses":[["seventh-amendment","Seventh Amendment (Civil Jury)"]],"text":"In Suits at common law, where the value in controversy shall exceed twenty dollars, the right of trial by jury shall be preserved, and no fact tried by a jury, shall be otherwise re-examined in any Court of the United States, than according to the rules of the common law.","by":{"0":"26","2":"21, 50"}},{"t":"usc","label":"15 U.S.C. § 1052","url":"https://www.law.cornell.edu/uscode/text/15/1052","subs":["(e)(1)"],"stext":{"head":"§1052. Trademarks registrable on principal register; concurrent registration","paras":[[0,"No trademark by which the goods of the applicant may be distinguished from the goods of others shall be refused registration on the principal register on account of its nature unless it—"],[0,"(a) Consists of or comprises immoral, deceptive, or scandalous matter; or matter which may disparage or falsely suggest a connection with persons, living or dead, institutions, beliefs, or national symbols, or bring them into contempt, or disrepute; or a geographical indication which, when used on or in connection with wines or spirits, identifies a place other than the origin of the goods and is first used on or in connection with wines or spirits by the applicant on or after one year after the date on which the WTO Agreement (as defined in section 3501(9) of title 19) enters into force with respect to the United States."],[0,"(b) Consists of or comprises the flag or coat of arms or other insignia of the United States, or of any State or municipality, or of any foreign nation, or any simulation thereof."],[0,"(c) Consists of or comprises a name, portrait, or signature identifying a particular living individual except by his written consent, or the name, signature, or portrait of a deceased President of the United States during the life of his widow, if any, except by the written consent of the widow."],[0,"(d) Consists of or comprises a mark which so resembles a mark registered in the Patent and Trademark Office, or a mark or trade name previously used in the United States by another and not abandoned, as to be likely, when used on or in connection with the goods of the applicant, to cause confusion, or to cause mistake, or to deceive: Provided, That if the Director determines that confusion, mistake, or deception is not likely to result from the continued use by more than one person of the same or similar marks under conditions and limitations as to the mode or place of use of the marks or the goods on or in connection with which such marks are used, concurrent registrations may be issued to such persons when they have become entitled to use such marks as a result of their concurrent lawful use in commerce prior to (1) the earliest of the filing dates of the applications pending or of any registration issued under this chapter; (2) July 5, 1947, in the case of registrations previously issued under the Act of March 3, 1881, or February 20, 1905, and continuing in full force and effect on that date; or (3) July 5, 1947, in the case of applications filed under the Act of February 20, 1905, and registered after July 5, 1947. Use prior to the filing date of any pending application or a registration shall not be required when the owner of such application or registration consents to the grant of a concurrent registration to the applicant. Concurrent registrations may also be issued by the Director when a court of competent jurisdiction has finally determined that more than one person is entitled to use the same or similar marks in commerce. In issuing concurrent registrations, the Director shall prescribe conditions and limitations as to the mode or place of use of the mark or the goods on or in connection with which such mark is registered to the respective persons."],[0,"(e) Consists of a mark which (1) when used on or in connection with the goods of the applicant is merely descriptive or deceptively misdescriptive of them, (2) when used on or in connection with the goods of the applicant is primarily geographically descriptive of them, except as indications of regional origin may be registrable under section 1054 of this title, (3) when used on or in connection with the goods of the applicant is primarily geographically deceptively misdescriptive of them, (4) is primarily merely a surname, or (5) comprises any matter that, as a whole, is functional."],[0,"(f) Except as expressly excluded in subsections (a), (b), (c), (d), (e)(3), and (e)(5) of this section, nothing in this chapter shall prevent the registration of a mark used by the applicant which has become distinctive of the applicant's goods in commerce. The Director may accept as prima facie evidence that the mark has become distinctive, as used on or in connection with the applicant's goods in commerce, proof of substantially exclusive and continuous use thereof as a mark by the applicant in commerce for the five years before the date on which the claim of distinctiveness is made. Nothing in this section shall prevent the registration of a mark which, when used on or in connection with the goods of the applicant, is primarily geographically deceptively misdescriptive of them, and which became distinctive of the applicant's goods in commerce before December 8, 1993."],[0,"A mark which would be likely to cause dilution by blurring or dilution by tarnishment under section 1125(c) of this title, may be refused registration only pursuant to a proceeding brought under section 1063 of this title. A registration for a mark which would be likely to cause dilution by blurring or dilution by tarnishment under section 1125(c) of this title, may be canceled pursuant to a proceeding brought under either section 1064 of this title or section 1092 of this title."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/15/1052?type=usc&year=mostrecent&link-type=html"},"head":"§1052. Trademarks registrable on principal register; concurrent registration","tname":"Commerce and Trade","by":{"0":"17, 18","1":"4, 5, 4, 5","2":"6"}},{"t":"usc","label":"15 U.S.C. § 1064","url":"https://www.law.cornell.edu/uscode/text/15/1064","stext":{"head":"§1064. Cancellation of registration","paras":[[0,"A petition to cancel a registration of a mark, stating the grounds relied upon, may, upon payment of the prescribed fee, be filed as follows by any person who believes that he is or will be damaged, including as a result of a likelihood of dilution by blurring or dilution by tarnishment under section 1125(c) of this title, by the registration of a mark on the principal register established by this chapter, or under the Act of March 3, 1881, or the Act of February 20, 1905:"],[1,"(1) Within five years from the date of the registration of the mark under this chapter."],[1,"(2) Within five years from the date of publication under section 1062(c) of this title of a mark registered under the Act of March 3, 1881, or the Act of February 20, 1905."],[1,"(3) At any time if the registered mark becomes the generic name for the goods or services, or a portion thereof, for which it is registered, or is functional, or has been abandoned, or its registration was obtained fraudulently or contrary to the provisions of section 1054 of this title or of subsection (a), (b), or (c) of section 1052 of this title for a registration under this chapter, or contrary to similar prohibitory provisions of such prior Acts for a registration under such Acts, or if the registered mark is being used by, or with the permission of, the registrant so as to misrepresent the source of the goods or services on or in connection with which the mark is used. If the registered mark becomes the generic name for less than all of the goods or services for which it is registered, a petition to cancel the registration for only those goods or services may be filed. A registered mark shall not be deemed to be the generic name of goods or services solely because such mark is also used as a name of or to identify a unique product or service. The primary significance of the registered mark to the relevant public rather than purchaser motivation shall be the test for determining whether the registered mark has become the generic name of goods or services on or in connection with which it has been used."],[1,"(4) At any time if the mark is registered under the Act of March 3, 1881, or the Act of February 20, 1905, and has not been published under the provisions of subsection (c) of section 1062 of this title."],[1,"(5) At any time in the case of a certification mark on the ground that the registrant (A) does not control, or is not able legitimately to exercise control over, the use of such mark, or (B) engages in the production or marketing of any goods or services to which the certification mark is applied, or (C) permits the use of the certification mark for purposes other than to certify, or (D) discriminately refuses to certify or to continue to certify the goods or services of any person who maintains the standards or conditions which such mark certifies."],[1,"(6) At any time after the 3-year period following the date of registration, if the registered mark has never been used in commerce on or in connection with some or all of the goods or services recited in the registration:"],[0,"Provided, That the Federal Trade Commission may apply to cancel on the grounds specified in paragraphs (3) and (5) of this section any mark registered on the principal register established by this chapter, and the prescribed fee shall not be required. Nothing in paragraph (5) shall be deemed to prohibit the registrant from using its certification mark in advertising or promoting recognition of the certification program or of the goods or services meeting the certification standards of the registrant. Such uses of the certification mark shall not be grounds for cancellation under paragraph (5), so long as the registrant does not itself produce, manufacture, or sell any of the certified goods or services to which its identical certification mark is applied. Nothing in paragraph (6) shall be construed to limit the timing applicable to any other ground for cancellation. A registration under section 1126(e) or 1141f of this title shall not be cancelled pursuant to paragraph (6) if the registrant demonstrates that any nonuse is due to special circumstances that excuse such nonuse."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/15/1064?type=usc&year=mostrecent&link-type=html"},"head":"§1064. Cancellation of registration","tname":"Commerce and Trade","by":{"0":"16, 18","2":"6"}},{"t":"usc","label":"15 U.S.C. § 1114","url":"https://www.law.cornell.edu/uscode/text/15/1114","subs":["(1)"],"stext":{"head":"§1114. Remedies; infringement; innocent infringement by printers and publishers","paras":[[0,"(1) Any person who shall, without the consent of the registrant—"],[1,"(a) use in commerce any reproduction, counterfeit, copy, or colorable imitation of a registered mark in connection with the sale, offering for sale, distribution, or advertising of any goods or services on or in connection with which such use is likely to cause confusion, or to cause mistake, or to deceive; or"],[1,"(b) reproduce, counterfeit, copy, or colorably imitate a registered mark and apply such reproduction, counterfeit, copy, or colorable imitation to labels, signs, prints, packages, wrappers, receptacles or advertisements intended to be used in commerce upon or in connection with the sale, offering for sale, distribution, or advertising of goods or services on or in connection with which such use is likely to cause confusion, or to cause mistake, or to deceive,"],[0,"shall be liable in a civil action by the registrant for the remedies hereinafter provided. Under subsection (b) hereof, the registrant shall not be entitled to recover profits or damages unless the acts have been committed with knowledge that such imitation is intended to be used to cause confusion, or to cause mistake, or to deceive."],[0,"As used in this paragraph, the term \"any person\" includes the United States, all agencies and instrumentalities thereof, and all individuals, firms, corporations, or other persons acting for the United States and with the authorization and consent of the United States, and any State, any instrumentality of a State, and any officer or employee of a State or instrumentality of a State acting in his or her official capacity. The United States, all agencies and instrumentalities thereof, and all individuals, firms, corporations, other persons acting for the United States and with the authorization and consent of the United States, and any State, and any such instrumentality, officer, or employee, shall be subject to the provisions of this chapter in the same manner and to the same extent as any nongovernmental entity."],[0,"(2) Notwithstanding any other provision of this chapter, the remedies given to the owner of a right infringed under this chapter or to a person bringing an action under section 1125(a) or (d) of this title shall be limited as follows:"],[1,"(A) Where an infringer or violator is engaged solely in the business of printing the mark or violating matter for others and establishes that he or she was an innocent infringer or innocent violator, the owner of the right infringed or person bringing the action under section 1125(a) of this title shall be entitled as against such infringer or violator only to an injunction against future printing."],[1,"(B) Where the infringement or violation complained of is contained in or is part of paid advertising matter in a newspaper, magazine, or other similar periodical or in an electronic communication as defined in section 2510(12) of title 18, the remedies of the owner of the right infringed or person bringing the action under section 1125(a) of this title as against the publisher or distributor of such newspaper, magazine, or other similar periodical or electronic communication shall be limited to an injunction against the presentation of such advertising matter in future issues of such newspapers, magazines, or other similar periodicals or in future transmissions of such electronic communications. The limitations of this subparagraph shall apply only to innocent infringers and innocent violators."],[1,"(C) Injunctive relief shall not be available to the owner of the right infringed or person bringing the action under section 1125(a) of this title with respect to an issue of a newspaper, magazine, or other similar periodical or an electronic communication containing infringing matter or violating matter where restraining the dissemination of such infringing matter or violating matter in any particular issue of such periodical or in an electronic communication would delay the delivery of such issue or transmission of such electronic communication after the regular time for such delivery or transmission, and such delay would be due to the method by which publication and distribution of such periodical or transmission of such electronic communication is customarily conducted in accordance with sound business practice, and not due to any method or device adopted to evade this section or to prevent or delay the issuance of an injunction or restraining order with respect to such infringing matter or violating matter."],[1,"(D)(i)(I) A domain name registrar, a domain name registry, or other domain name registration authority that takes any action described under clause (ii) affecting a domain name shall not be liable for monetary relief or, except as provided in subclause (II), for injunctive relief, to any person for such action, regardless of whether the domain name is finally determined to infringe or dilute the mark."],[1,"(II) A domain name registrar, domain name registry, or other domain name registration authority described in subclause (I) may be subject to injunctive relief only if such registrar, registry, or other registration authority has—"],[2,"(aa) not expeditiously deposited with a court, in which an action has been filed regarding the disposition of the domain name, documents sufficient for the court to establish the court's control and authority regarding the disposition of the registration and use of the domain name;"],[2,"(bb) transferred, suspended, or otherwise modified the domain name during the pendency of the action, except upon order of the court; or"],[2,"(cc) willfully failed to comply with any such court order."],[1,"(ii) An action referred to under clause (i)(I) is any action of refusing to register, removing from registration, transferring, temporarily disabling, or permanently canceling a domain name—"],[2,"(I) in compliance with a court order under section 1125(d) of this title; or"],[2,"(II) in the implementation of a reasonable policy by such registrar, registry, or authority prohibiting the registration of a domain name that is identical to, confusingly similar to, or dilutive of another's mark."],[1,"(iii) A domain name registrar, a domain name registry, or other domain name registration authority shall not be liable for damages under this section for the registration or maintenance of a domain name for another absent a showing of bad faith intent to profit from such registration or maintenance of the domain name."],[1,"(iv) If a registrar, registry, or other registration authority takes an action described under clause (ii) based on a knowing and material misrepresentation by any other person that a domain name is identical to, confusingly similar to, or dilutive of a mark, the person making the knowing and material misrepresentation shall be liable for any damages, including costs and attorney's fees, incurred by the domain name registrant as a result of such action. The court may also grant injunctive relief to the domain name registrant, including the reactivation of the domain name or the transfer of the domain name to the domain name registrant."],[1,"(v) A domain name registrant whose domain name has been suspended, disabled, or transferred under a policy described under clause (ii)(II) may, upon notice to the mark owner, file a civil action to establish that the registration or use of the domain name by such registrant is not unlawful under this chapter. The court may grant injunctive relief to the domain name registrant, including the reactivation of the domain name or transfer of the domain name to the domain name registrant."],[1,"(E) As used in this paragraph—"],[2,"(i) the term \"violator\" means a person who violates section 1125(a) of this title; and"],[2,"(ii) the term \"violating matter\" means matter that is the subject of a violation under section 1125(a) of this title."],[0,"(3)(A) Any person who engages in the conduct described in paragraph (11) of section 110 of title 17 and who complies with the requirements set forth in that paragraph is not liable on account of such conduct for a violation of any right under this chapter. This subparagraph does not preclude liability, nor shall it be construed to restrict the defenses or limitations on rights granted under this chapter, of a person for conduct not described in paragraph (11) of section 110 of title 17, even if that person also engages in conduct described in paragraph (11) of section 110 of such title."],[0,"(B) A manufacturer, licensee, or licensor of technology that enables the making of limited portions of audio or video content of a motion picture imperceptible as described in subparagraph (A) is not liable on account of such manufacture or license for a violation of any right under this chapter, if such manufacturer, licensee, or licensor ensures that the technology provides a clear and conspicuous notice at the beginning of each performance that the performance of the motion picture is altered from the performance intended by the director or copyright holder of the motion picture. The limitations on liability in subparagraph (A) and this subparagraph shall not apply to a manufacturer, licensee, or licensor of technology that fails to comply with this paragraph."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/15/1114?type=usc&year=mostrecent&link-type=html"},"head":"§1114. Remedies; infringement; innocent infringement by printers and publishers","tname":"Commerce and Trade","by":{"0":"1, 10","1":"1, 6","2":"7"}},{"t":"usc","label":"15 U.S.C. § 1125","url":"https://www.law.cornell.edu/uscode/text/15/1125","subs":["(a)(1)(A)"],"stext":{"head":"§1125. False designations of origin, false descriptions, and dilution forbidden","paras":[[0,"(a) Civil action"],[0,"(1) Any person who, on or in connection with any goods or services, or any container for goods, uses in commerce any word, term, name, symbol, or device, or any combination thereof, or any false designation of origin, false or misleading description of fact, or false or misleading representation of fact, which—"],[1,"(A) is likely to cause confusion, or to cause mistake, or to deceive as to the affiliation, connection, or association of such person with another person, or as to the origin, sponsorship, or approval of his or her goods, services, or commercial activities by another person, or"],[1,"(B) in commercial advertising or promotion, misrepresents the nature, characteristics, qualities, or geographic origin of his or her or another person's goods, services, or commercial activities,"],[0,"shall be liable in a civil action by any person who believes that he or she is or is likely to be damaged by such act."],[0,"(2) As used in this subsection, the term \"any person\" includes any State, instrumentality of a State or employee of a State or instrumentality of a State acting in his or her official capacity. Any State, and any such instrumentality, officer, or employee, shall be subject to the provisions of this chapter in the same manner and to the same extent as any nongovernmental entity."],[0,"(3) In a civil action for trade dress infringement under this chapter for trade dress not registered on the principal register, the person who asserts trade dress protection has the burden of proving that the matter sought to be protected is not functional."],[0,"(b) Importation"],[0,"Any goods marked or labeled in contravention of the provisions of this section shall not be imported into the United States or admitted to entry at any customhouse of the United States. The owner, importer, or consignee of goods refused entry at any customhouse under this section may have any recourse by protest or appeal that is given under the customs revenue laws or may have the remedy given by this chapter in cases involving goods refused entry or seized."],[0,"(c) Dilution by blurring; dilution by tarnishment"],[0,"(1) Injunctive relief"],[1,"Subject to the principles of equity, the owner of a famous mark that is distinctive, inherently or through acquired distinctiveness, shall be entitled to an injunction against another person who, at any time after the owner's mark has become famous, commences use of a mark or trade name in commerce that is likely to cause dilution by blurring or dilution by tarnishment of the famous mark, regardless of the presence or absence of actual or likely confusion, of competition, or of actual economic injury."],[0,"(2) Definitions"],[1,"(A) For purposes of paragraph (1), a mark is famous if it is widely recognized by the general consuming public of the United States as a designation of source of the goods or services of the mark's owner. In determining whether a mark possesses the requisite degree of recognition, the court may consider all relevant factors, including the following:"],[2,"(i) The duration, extent, and geographic reach of advertising and publicity of the mark, whether advertised or publicized by the owner or third parties."],[2,"(ii) The amount, volume, and geographic extent of sales of goods or services offered under the mark."],[2,"(iii) The extent of actual recognition of the mark."],[2,"(iv) Whether the mark was registered under the Act of March 3, 1881, or the Act of February 20, 1905, or on the principal register."],[1,"(B) For purposes of paragraph (1), \"dilution by blurring\" is association arising from the similarity between a mark or trade name and a famous mark that impairs the distinctiveness of the famous mark. In determining whether a mark or trade name is likely to cause dilution by blurring, the court may consider all relevant factors, including the following:"],[2,"(i) The degree of similarity between the mark or trade name and the famous mark."],[2,"(ii) The degree of inherent or acquired distinctiveness of the famous mark."],[2,"(iii) The extent to which the owner of the famous mark is engaging in substantially exclusive use of the mark."],[2,"(iv) The degree of recognition of the famous mark."],[2,"(v) Whether the user of the mark or trade name intended to create an association with the famous mark."],[2,"(vi) Any actual association between the mark or trade name and the famous mark."],[1,"(C) For purposes of paragraph (1), \"dilution by tarnishment\" is association arising from the similarity between a mark or trade name and a famous mark that harms the reputation of the famous mark."],[0,"(3) Exclusions"],[1,"The following shall not be actionable as dilution by blurring or dilution by tarnishment under this subsection:"],[2,"(A) Any fair use, including a nominative or descriptive fair use, or facilitation of such fair use, of a famous mark by another person other than as a designation of source for the person's own goods or services, including use in connection with—"],[3,"(i) advertising or promotion that permits consumers to compare goods or services; or"],[3,"(ii) identifying and parodying, criticizing, or commenting upon the famous mark owner or the goods or services of the famous mark owner."],[2,"(B) All forms of news reporting and news commentary."],[2,"(C) Any noncommercial use of a mark."],[0,"(4) Burden of proof"],[1,"In a civil action for trade dress dilution under this chapter for trade dress not registered on the principal register, the person who asserts trade dress protection has the burden of proving that—"],[2,"(A) the claimed trade dress, taken as a whole, is not functional and is famous; and"],[2,"(B) if the claimed trade dress includes any mark or marks registered on the principal register, the unregistered matter, taken as a whole, is famous separate and apart from any fame of such registered marks."],[0,"(5) Additional remedies"],[1,"In an action brought under this subsection, the owner of the famous mark shall be entitled to injunctive relief as set forth in section 1116 of this title. The owner of the famous mark shall also be entitled to the remedies set forth in sections 1117(a) and 1118 of this title, subject to the discretion of the court and the principles of equity if—"],[2,"(A) the mark or trade name that is likely to cause dilution by blurring or dilution by tarnishment was first used in commerce by the person against whom the injunction is sought after October 6, 2006; and"],[2,"(B) in a claim arising under this subsection—"],[3,"(i) by reason of dilution by blurring, the person against whom the injunction is sought willfully intended to trade on the recognition of the famous mark; or"],[3,"(ii) by reason of dilution by tarnishment, the person against whom the injunction is sought willfully intended to harm the reputation of the famous mark."],[0,"(6) Ownership of valid registration a complete bar to action"],[1,"The ownership by a person of a valid registration under the Act of March 3, 1881, or the Act of February 20, 1905, or on the principal register under this chapter shall be a complete bar to an action against that person, with respect to that mark, that—"],[2,"(A) is brought by another person under the common law or a statute of a State; and"],[2,"(B)(i) seeks to prevent dilution by blurring or dilution by tarnishment; or"],[2,"(ii) asserts any claim of actual or likely damage or harm to the distinctiveness or reputation of a mark, label, or form of advertisement."],[0,"(7) Savings clause"],[1,"Nothing in this subsection shall be construed to impair, modify, or supersede the applicability of the patent laws of the United States."],[0,"(d) Cyberpiracy prevention"],[0,"(1)(A) A person shall be liable in a civil action by the owner of a mark, including a personal name which is protected as a mark under this section, if, without regard to the goods or services of the parties, that person—"],[1,"(i) has a bad faith intent to profit from that mark, including a personal name which is protected as a mark under this section; and"],[1,"(ii) registers, traffics in, or uses a domain name that—"],[2,"(I) in the case of a mark that is distinctive at the time of registration of the domain name, is identical or confusingly similar to that mark;"],[2,"(II) in the case of a famous mark that is famous at the time of registration of the domain name, is identical or confusingly similar to or dilutive of that mark; or"],[2,"(III) is a trademark, word, or name protected by reason of section 706 of title 18 or section 220506 of title 36."],[0,"(B)(i) In determining whether a person has a bad faith intent described under subparagraph (A), a court may consider factors such as, but not limited to—"],[1,"(I) the trademark or other intellectual property rights of the person, if any, in the domain name;"],[1,"(II) the extent to which the domain name consists of the legal name of the person or a name that is otherwise commonly used to identify that person;"],[1,"(III) the person's prior use, if any, of the domain name in connection with the bona fide offering of any goods or services;"],[1,"(IV) the person's bona fide noncommercial or fair use of the mark in a site accessible under the domain name;"],[1,"(V) the person's intent to divert consumers from the mark owner's online location to a site accessible under the domain name that could harm the goodwill represented by the mark, either for commercial gain or with the intent to tarnish or disparage the mark, by creating a likelihood of confusion as to the source, sponsorship, affiliation, or endorsement of the site;"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/15/1125?type=usc&year=mostrecent&link-type=html"},"head":"§1125. False designations of origin, false descriptions, and dilution forbidden","tname":"Commerce and Trade","by":{"0":"16, 17, 18","1":"1, 6","2":"7, 45"}},{"t":"usc","label":"15 U.S.C. § 1127","url":"https://www.law.cornell.edu/uscode/text/15/1127","stext":{"head":"§1127. Construction and definitions; intent of chapter","paras":[[0,"In the construction of this chapter, unless the contrary is plainly apparent from the context—"],[0,"The United States includes and embraces all territory which is under its jurisdiction and control."],[0,"The word \"commerce\" means all commerce which may lawfully be regulated by Congress."],[0,"The term \"principal register\" refers to the register provided for by sections 1051 to 1072 of this title, and the term \"supplemental register\" refers to the register provided for by sections 1091 to 1096 of this title."],[0,"The term \"person\" and any other word or term used to designate the applicant or other entitled to a benefit or privilege or rendered liable under the provisions of this chapter includes a juristic person as well as a natural person. The term \"juristic person\" includes a firm, corporation, union, association, or other organization capable of suing and being sued in a court of law."],[0,"The term \"person\" also includes the United States, any agency or instrumentality thereof, or any individual, firm, or corporation acting for the United States and with the authorization and consent of the United States. The United States, any agency or instrumentality thereof, and any individual, firm, or corporation acting for the United States and with the authorization and consent of the United States, shall be subject to the provisions of this chapter in the same manner and to the same extent as any nongovernmental entity."],[0,"The term \"person\" also includes any State, any instrumentality of a State, and any officer or employee of a State or instrumentality of a State acting in his or her official capacity. Any State, and any such instrumentality, officer, or employee, shall be subject to the provisions of this chapter in the same manner and to the same extent as any nongovernmental entity."],[0,"The terms \"applicant\" and \"registrant\" embrace the legal representatives, predecessors, successors and assigns of such applicant or registrant."],[0,"The term \"Director\" means the Under Secretary of Commerce for Intellectual Property and Director of the United States Patent and Trademark Office."],[0,"The term \"related company\" means any person whose use of a mark is controlled by the owner of the mark with respect to the nature and quality of the goods or services on or in connection with which the mark is used."],[0,"The terms \"trade name\" and \"commercial name\" mean any name used by a person to identify his or her business or vocation."],[0,"The term \"trademark\" includes any word, name, symbol, or device, or any combination thereof—"],[1,"(1) used by a person, or"],[1,"(2) which a person has a bona fide intention to use in commerce and applies to register on the principal register established by this chapter,"],[0,"to identify and distinguish his or her goods, including a unique product, from those manufactured or sold by others and to indicate the source of the goods, even if that source is unknown."],[0,"The term \"service mark\" means any word, name, symbol, or device, or any combination thereof—"],[1,"(1) used by a person, or"],[1,"(2) which a person has a bona fide intention to use in commerce and applies to register on the principal register established by this chapter,"],[0,"to identify and distinguish the services of one person, including a unique service, from the services of others and to indicate the source of the services, even if that source is unknown. Titles, character names, and other distinctive features of radio or television programs may be registered as service marks notwithstanding that they, or the programs, may advertise the goods of the sponsor."],[0,"The term \"certification mark\" means any word, name, symbol, or device, or any combination thereof—"],[1,"(1) used by a person other than its owner, or"],[1,"(2) which its owner has a bona fide intention to permit a person other than the owner to use in commerce and files an application to register on the principal register established by this chapter,"],[0,"to certify regional or other origin, material, mode of manufacture, quality, accuracy, or other characteristics of such person's goods or services or that the work or labor on the goods or services was performed by members of a union or other organization."],[0,"The term \"collective mark\" means a trademark or service mark—"],[1,"(1) used by the members of a cooperative, an association, or other collective group or organization, or"],[1,"(2) which such cooperative, association, or other collective group or organization has a bona fide intention to use in commerce and applies to register on the principal register established by this chapter,"],[0,"and includes marks indicating membership in a union, an association, or other organization."],[0,"The term \"mark\" includes any trademark, service mark, collective mark, or certification mark."],[0,"The term \"use in commerce\" means the bona fide use of a mark in the ordinary course of trade, and not made merely to reserve a right in a mark. For purposes of this chapter, a mark shall be deemed to be in use in commerce—"],[1,"(1) on goods when—"],[2,"(A) it is placed in any manner on the goods or their containers or the displays associated therewith or on the tags or labels affixed thereto, or if the nature of the goods makes such placement impracticable, then on documents associated with the goods or their sale, and"],[2,"(B) the goods are sold or transported in commerce, and"],[1,"(2) on services when it is used or displayed in the sale or advertising of services and the services are rendered in commerce, or the services are rendered in more than one State or in the United States and a foreign country and the person rendering the services is engaged in commerce in connection with the services."],[0,"A mark shall be deemed to be \"abandoned\" if either of the following occurs:"],[1,"(1) When its use has been discontinued with intent not to resume such use. Intent not to resume may be inferred from circumstances. Nonuse for 3 consecutive years shall be prima facie evidence of abandonment. \"Use\" of a mark means the bona fide use of such mark made in the ordinary course of trade, and not made merely to reserve a right in a mark."],[1,"(2) When any course of conduct of the owner, including acts of omission as well as commission, causes the mark to become the generic name for the goods or services on or in connection with which it is used or otherwise to lose its significance as a mark. Purchaser motivation shall not be a test for determining abandonment under this paragraph."],[0,"The term \"colorable imitation\" includes any mark which so resembles a registered mark as to be likely to cause confusion or mistake or to deceive."],[0,"The term \"registered mark\" means a mark registered in the United States Patent and Trademark Office under this chapter or under the Act of March 3, 1881, or the Act of February 20, 1905, or the Act of March 19, 1920. The phrase \"marks registered in the Patent and Trademark Office\" means registered marks."],[0,"The term \"Act of March 3, 1881\", \"Act of February 20, 1905\", or \"Act of March 19, 1920\", means the respective Act as amended."],[0,"A \"counterfeit\" is a spurious mark which is identical with, or substantially indistinguishable from, a registered mark."],[0,"The term \"domain name\" means any alphanumeric designation which is registered with or assigned by any domain name registrar, domain name registry, or other domain name registration authority as part of an electronic address on the Internet."],[0,"The term \"Internet\" has the meaning given that term in section 230(f)(1) of title 47."],[0,"Words used in the singular include the plural and vice versa."],[0,"The intent of this chapter is to regulate commerce within the control of Congress by making actionable the deceptive and misleading use of marks in such commerce; to protect registered marks used in such commerce from interference by State, or territorial legislation; to protect persons engaged in such commerce against unfair competition; to prevent fraud and deception in such commerce by the use of reproductions, copies, counterfeits, or colorable imitations of registered marks; and to provide rights and remedies stipulated by treaties and conventions respecting trademarks, trade names, and unfair competition entered into between the United States and foreign nations."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/15/1127?type=usc&year=mostrecent&link-type=html"},"head":"§1127. Construction and definitions; intent of chapter","tname":"Commerce and Trade","by":{"0":"4","1":"3"}},{"t":"usc","label":"28 U.S.C. § 1254","url":"https://www.law.cornell.edu/uscode/text/28/1254","by":{"0":"1"}},{"t":"rule","label":"Fed. R. Civ. P. 52","url":"https://www.law.cornell.edu/rules/frcp/rule_52","by":{"0":"25"}},{"t":"law","label":"Pub. L. No. 100-667","url":"https://www.govinfo.gov/link/statute/102/3935","by":{"0":"20"}},{"t":"case","label":"Anderson v. Liberty Lobby, Inc.","cite":"477 U.S. 242","y":1986,"id":"1985/84-1602","sc":1,"sum":"In a 6-to-3 opinion, the Court held that the purpose of summary judgments is to determine if the evidence is so one-sided that a party should prevail as a matter of law. Summary judgments will not lie if there is a sufficient likelihood that a reasonable jury would return a verdict favorable to the nonmoving party.","sumSrc":"Oyez","by":{"1":"16, 17, 30, 31"}},{"t":"case","label":"Bufkin v. Collins","cite":"604 U.S. 369","y":2025,"url":"https://supreme.justia.com/cases/federal/us/604/369/","sc":1,"by":{"1":"26","2":"47"}},{"t":"case","label":"Car-Freshner Corp. v. American Covers, LLC","cite":"980 F.3d 314","y":2020,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/980/314/","by":{"1":"29"}},{"t":"case","label":"First Sav. Bank, F.S.B. v. First Bank Sys., Inc.","cite":"101 F.3d 645","y":1996,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/101/645/","by":{"1":"7"}},{"t":"case","label":"Florida Int’l Univ. Bd. of Trs. v. Florida Nat’l Univ., Inc.","cite":"830 F.3d 1242","y":2016,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/830/1242/","by":{"1":"7"}},{"t":"case","label":"Lang v. Retirement Living Publ’g Co.","cite":"949 F.2d 576","y":1991,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.2d/949/576/","by":{"1":"8"}},{"t":"case","label":"Loper Bright Enters. v. Raimondo","cite":"603 U.S. 369","y":2024,"id":"2023/22-451","sc":1,"sum":"The Administrative Procedure Act requires courts to exercise their independent judgment in deciding whether an agency has acted within its statutory authority, and courts may not defer to an agency interpretation of the law simply because a statute is ambiguous; Chevron U. S. A. Inc. v. Natural Resources Defense Council, Inc., 467 U. S. 837, is overruled.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"25","2":"24"}},{"t":"case","label":"Mattel, Inc. v. MCA Records, Inc.","cite":"296 F.3d 894","y":2002,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/296/894/","sum":"Explaining that “trademark law … can be used to suppress free speech”.","sumSrc":"brief:2","by":{"1":"23","2":"26"}},{"t":"case","label":"Max Rack, Inc. v. Core Health & Fitness, LLC","cite":"40 F.4th 454","y":2022,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.4th/40/454/","by":{"1":"30"}},{"t":"case","label":"Monasky v. Taglieri","cite":"589 U.S. 68","y":2020,"id":"2019/18-935","sc":1,"sum":"The Court held that a child’s “habitual residence” under the Hague Convention depends on the totality of the circumstances specific to the case, not categorical requirements such as an actual agreement between parents.","sumSrc":"Oyez","by":{"1":"16","2":"51"}},{"t":"case","label":"New York Stock Exch., Inc. v. New York, New York Hotel, LLC","cite":"293 F.3d 550","y":2002,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/293/550/","by":{"1":"22"}},{"t":"case","label":"Ornelas v. United States","cite":"517 U.S. 690","y":1996,"id":"1995/95-5257","sc":1,"sum":"Announced by Chief Justice William H. Rehnquist, the Court held \"[t]he ultimate questions of reasonable suspicion and probable cause to make a warrantless search should be reviewed de novo.\" The principle details in such a review should be an analysis of events leading up to the search and the objective review of the search.","sumSrc":"Oyez","by":{"1":"26","2":"46"}},{"t":"case","label":"Plus Prods. v. Plus Disc. Foods, Inc.","cite":"722 F.2d 999","y":1983,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.2d/722/999/","by":{"1":"22"}},{"t":"case","label":"Santa Fe Indep. Sch. Dist. v. Doe","cite":"530 U.S. 290","y":2000,"id":"1999/99-62","sc":1,"sum":"The Court held that a public school district's policy permitting student-led, student-initiated prayer at football games violated the Establishment Clause.","sumSrc":"Oyez","by":{"1":"26"}},{"t":"case","label":"Savin Corp. v. Savin Grp.","cite":"391 F.3d 439","y":2004,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/391/439/","by":{"1":"20"}},{"t":"case","label":"Souza v. Exotic Island Enters., Inc.","cite":"68 F.4th 99","y":2023,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.4th/68/99/","by":{"1":"30","2":"23, 30"}},{"t":"case","label":"Star Indus., Inc. v. Bacardi & Co.","cite":"412 F.3d 373","y":2005,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/412/373/","by":{"1":"8"}},{"t":"case","label":"Variety Stores, Inc. v. Wal-Mart Stores, Inc.","cite":"888 F.3d 651","y":2018,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/888/651/","by":{"1":"8","2":"35"}},{"t":"case","label":"Wal-Mart Stores, Inc. v. Samara Bros.","cite":"529 U.S. 205","y":2000,"id":"1999/99-150","sc":1,"sum":"The Court held that \"[i]n a section 43(a) action for infringement of unregistered trade dress, a product's design is distinctive, and therefore protectible, only upon a showing of secondary meaning.","sumSrc":"Oyez","by":{"1":"4, 6","2":"25, 33"}},{"t":"const","label":"Amendment IV","clauses":[["fourth-amendment","Fourth Amendment"]],"text":"The right of the people to be secure in their persons, houses, papers, and effects, against unreasonable searches and seizures, shall not be violated, and no Warrants shall issue, but upon probable cause, supported by Oath or affirmation, and particularly describing the place to be searched, and the persons or things to be seized.","by":{"1":"27"}},{"t":"usc","label":"15 U.S.C. § 1051","url":"https://www.law.cornell.edu/uscode/text/15/1051","by":{"1":"3, 4"}},{"t":"usc","label":"15 U.S.C. § 1057","url":"https://www.law.cornell.edu/uscode/text/15/1057","subs":["(b)"],"by":{"1":"6"}},{"t":"usc","label":"15 U.S.C. § 1062","url":"https://www.law.cornell.edu/uscode/text/15/1062","by":{"1":"1"}},{"t":"usc","label":"15 U.S.C. § 1065","url":"https://www.law.cornell.edu/uscode/text/15/1065","by":{"1":"6"}},{"t":"usc","label":"15 U.S.C. § 1122","url":"https://www.law.cornell.edu/uscode/text/15/1122","subs":["(a)","(c)"],"by":{"1":"1, 1"}},{"t":"usc","label":"35 U.S.C. § 2","url":"https://www.law.cornell.edu/uscode/text/35/2","by":{"1":"1"}},{"t":"rule","label":"Fed. R. Civ. P. 56","url":"https://www.law.cornell.edu/rules/frcp/rule_56","subs":["(a)"],"by":{"1":"16, 17, 30, 32","2":"51"}},{"t":"case","label":"Allsup, Inc. v. Advantage 2000 Consultants Inc.","cite":"428 F.3d 1135","y":2005,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.3d/428/1135/","by":{"2":"45"}},{"t":"case","label":"Andy Warhol Found. for the Visual Arts, Inc. v. Goldsmith","cite":"598 U.S. 508","y":2023,"id":"2022/21-869","sc":1,"sum":"The “purpose and character” of the Andy Warhol Foundation’s particular commercial use of Lynn Goldsmith’s photograph—17 U. S. C. §107(1)—does not favor AWF’s “fair use” defense to copyright infringement.","sumSrc":"Holding (supremecourt.gov)","by":{"2":"30"}},{"t":"case","label":"Apple Comput., Inc. v. Microsoft Corp.","cite":"35 F.3d 1435","y":1994,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/35/1435/","by":{"2":"28"}},{"t":"case","label":"Bondi v. VanDerStok","cite":"604 U.S. 458","y":2025,"id":"2024/23-852","sc":1,"sum":"ATF's 2022 Rule interpreting the Gun Control Act of 1968 to cover certain products that can readily be converted into an operational firearm or a functional frame or receiver, see 27 CFR §§478.11, 478.12(c), is not facially inconsistent with the Act.","sumSrc":"Holding (supremecourt.gov)","by":{"2":"49"}},{"t":"case","label":"Bose Corp. v. Consumers Union of U.S., Inc.","cite":"466 U.S. 485","y":1984,"id":"1983/82-1246","sc":1,"sum":"The Court held that while the record revealed that the article's author mistakenly described the sound path of Bose speakers, he did not do so with actual malice.","sumSrc":"Oyez","by":{"2":"26-27, 46-47"}},{"t":"case","label":"Brookfield Commc’ns, Inc. v. West Coast Entm’t Corp.","cite":"174 F.3d 1036","y":1999,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/174/1036/","sum":"Noting that “[s]ome weak marks are weaker than others”.","sumSrc":"brief:2","by":{"2":"35"}},{"t":"case","label":"Campbell v. Acuff-Rose Music, Inc.","cite":"510 U.S. 569","y":1994,"id":"1993/92-1292","sc":1,"sum":"The Court held that a parody's commercial character is only one element to be weighed in a fair use enquiry and that insufficient consideration was given to the nature of parody in weighing the degree of copying.","sumSrc":"Oyez","by":{"2":"30"}},{"t":"case","label":"CareFirst of Md., Inc. v. First Care, P.C.","cite":"434 F.3d 263","y":2006,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/434/263/","by":{"2":"8, 35"}},{"t":"case","label":"Centaur Commc’ns, Ltd. v. A/S/M Commc’ns, Inc.","cite":"830 F.2d 1217","y":1987,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.2d/830/1217/","by":{"2":"54"}},{"t":"case","label":"Cook, Perkiss & Liehe, Inc. v. N. Cal. Collection Serv. Inc.","cite":"911 F.2d 242","y":1990,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.2d/911/242/","by":{"2":"45"}},{"t":"case","label":"Del. & Hudson Canal Co. v. Clark","cite":"80 U.S. 311","y":1871,"id":"scdb/1871-105","sc":1,"sum":"In the northeastern section of Pennsylvania there exists a place or region to which from early times the name of Lorckaworna, or Lackawanna, seems, on the few occasions when the place is mentioned, to have been given. As early as 1793, the diary of William Colbert, a pioneer preacher of the Methodists, makes record of his meeting a person who lived at “Lackawanna,” and of his crossing a mountain and getting there …","sumSrc":"Headnote (U.S. Reports)","by":{"2":"4, 33"}},{"t":"case","label":"Dupree v. Younger","cite":"598 U.S. 729","y":2023,"id":"2022/22-210","sc":1,"sum":"A post-trial motion under Federal Rule of Civil Procedure 50 is not required to preserve for appellate review a purely legal issue resolved at summary judgment.","sumSrc":"Holding (supremecourt.gov)","by":{"2":"23"}},{"t":"case","label":"Elgin Nat’l Watch Co. v. Ill. Watch Case Co.","cite":"179 U.S. 665","y":1901,"id":"scdb/1900-085","sc":1,"sum":"The term trade mark means a distinctive mark of authenticity, through which the products of particular manufacturers or the vendible commodities of particular merchants may be distinguished from those of others.","sumSrc":"Headnote (U.S. Reports)","by":{"2":"4"}},{"t":"case","label":"FCC v. Fox Television Stations, Inc.","cite":"567 U.S. 239","y":2012,"id":"2011/10-1293","sc":1,"sum":"The Court determined that an FCC policy regarding profane language was too vague, and which was remanded to the Second Circuit Court of Appeals to determine if the FCC violated its customers' First Amendment rights.","sumSrc":"Oyez","by":{"2":"46"}},{"t":"case","label":"FedEx Ground Package Sys., Inc. v. Route Consultant, Inc.","cite":"97 F.4th 444","y":2024,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.4th/97/444/","by":{"2":"45"}},{"t":"case","label":"Feist Publ’ns, Inc. v. Rural Tel. Serv. Co.","cite":"499 U.S. 340","y":1991,"id":"1990/89-1909","sc":1,"sum":"The Court held that the names, towns, and telephone numbers copied by Feist were not original to Rural and therefore were not protected by the copyright in Rural's combined white and yellow pages directory.","sumSrc":"Oyez","by":{"2":"28"}},{"t":"case","label":"Festo Corp. v. Shoketsu Kinzoku Kogyo Kabushiki Co.","cite":"535 U.S. 722","y":2002,"id":"2001/00-1543","sc":1,"sum":"The Court held that prosecution history estoppel may apply to any claim amendment made to satisfy the Patent Act's requirements, not just to amendments made to avoid the prior art, but that estoppel need not bar suit against every equivalent to the amended claim element.","sumSrc":"Oyez","by":{"2":"29"}},{"t":"case","label":"Free Speech Coal., Inc. v. Paxton","cite":"606 U.S. 461","y":2025,"id":"2024/23-1122","sc":1,"sum":"Texas law H. B. 1181—which requires certain commercial websites publishing sexually explicit content that is obscene to minors to verify that visitors are 18 or older— only incidentally burdens the protected speech of adults and survives intermediate scrutiny under the First Amendment’s Free Speech Clause.","sumSrc":"Holding (supremecourt.gov)","by":{"2":"46"}},{"t":"case","label":"Gaiman v. McFarlane","cite":"360 F.3d 644","y":2004,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/360/644/","by":{"2":"28"}},{"t":"case","label":"Georgia v. Brailsford","cite":"3 U.S. 1","y":1794,"id":"scdb/1794-001","sc":1,"sum":"ON the meeting of the Court, a commission was read, dated the 28th of January, 1794, appointing William Bradford, Esquire, Attorney-General of the United States","sumSrc":"Headnote (U.S. Reports)","by":{"2":"50"}},{"t":"case","label":"Global-Tech Appliances, Inc. v. SEB S.A.","cite":"563 U.S. 754","y":2011,"id":"2010/10-6","sc":1,"sum":"The Court ruled that induced infringement under the patent clause requires knowledge that the induced acts constitute patent infringement.","sumSrc":"Oyez","by":{"2":"51"}},{"t":"case","label":"Google LLC v. Oracle Am., Inc.","cite":"593 U.S. 1","y":2021,"id":"2020/18-956","sc":1,"sum":"Google’s limited copying of the Java SE Application Programming Interface allowed programmers to put their accrued talents to work in a transformative program and constituted a fair use of that material under copyright law.","sumSrc":"Holding (supremecourt.gov)","by":{"2":"23, 29-30"}},{"t":"case","label":"Hamilton-Brown Shoe Co. v. Wolf Bros. & Co.","cite":"240 U.S. 251","y":1916,"id":"scdb/1915-097","sc":1,"sum":"The words “The American Girl” as applied to women’s shoes is not a geographical or descriptive term signifying that the articles are manufactured in America, or intended to be.sold therein; nor does it indicate qualities or characteristics of the article.","sumSrc":"Headnote (U.S. Reports)","by":{"2":"4, 47-48"}},{"t":"case","label":"Henri’s Food Prods. Co. v. Tasty Snacks, Inc.","cite":"817 F.2d 1303","y":1987,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.2d/817/1303/","by":{"2":"48"}},{"t":"case","label":"I Dig Texas, LLC v. Creager","cite":"98 F.4th 998","y":2024,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.4th/98/998/","by":{"2":"45"}},{"t":"case","label":"Iancu v. Brunetti","cite":"588 U.S. 388","y":2019,"id":"2018/18-302","sc":1,"sum":"The Lanham Act prohibition on the registration of “immoral” or “scandalous” trademarks infringes the First Amendment.","sumSrc":"Holding (supremecourt.gov)","by":{"2":"5"}},{"t":"case","label":"InSinkErator, LLC v. Joneca Co.","cite":"163 F.4th 608","y":2025,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.4th/163/608/","by":{"2":"45"}},{"t":"case","label":"Int’l Kennel Club of Chi., Inc. v. Mighty Star, Inc.","cite":"846 F.2d 1079","y":1988,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.2d/846/1079/","by":{"2":"7"}},{"t":"case","label":"John H. Harland Co. v. Clarke Checks, Inc.","cite":"711 F.2d 966","y":1983,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.2d/711/966/","sum":"Concluding that mark is “not particularly strong”.","sumSrc":"brief:2","by":{"2":"35"}},{"t":"case","label":"Kellogg Co. v. Toucan Golf, Inc.","cite":"337 F.3d 616","y":2003,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/337/616/","by":{"2":"48"}},{"t":"case","label":"Kibler v. Hall","cite":"583 U.S. 820","y":2017,"url":"https://supreme.justia.com/cases/federal/us/583/820/","sc":1,"by":{"2":"50"}},{"t":"case","label":"KSR Int’l Co. v. Teleflex Inc.","cite":"550 U.S. 398","y":2007,"id":"2006/04-1350","sc":1,"sum":"The Court ruled unanimously that the Federal Circuit \"analyzed the issue in a narrow, rigid manner inconsistent with [Section 103(a)] and our precedents.\" Justice Anthony Kennedy wrote the opinion for the Court, which ruled in favor of KSR and reversed the Court of Appeals.","sumSrc":"Oyez","by":{"2":"28"}},{"t":"case","label":"M&G Polymers USA, LLC v. Tackett","cite":"574 U.S. 427","y":2015,"id":"2014/13-1010","sc":1,"sum":"The Court ruled that collective bargaining agreements should always be interpreted according to ordinary principles of contract law.","sumSrc":"Oyez","by":{"2":"24"}},{"t":"case","label":"Matal v. Tam","cite":"582 U.S. 218","y":2017,"id":"2016/15-1293","sc":1,"sum":"The Court determined that the Disparagement Clause prohibits trademarks that disparage the members of a racial or ethnic group and violates the Free Speech Clause of the First Amendment.","sumSrc":"Oyez","by":{"2":"4, 6"}},{"t":"case","label":"Miller v. California","cite":"413 U.S. 15","y":1973,"id":"1971/70-73","sc":1,"sum":"The Court found that \"obscene materials\" do not have First Amendment protection.","sumSrc":"Oyez","by":{"2":"46"}},{"t":"case","label":"Miller v. Fenton","cite":"474 U.S. 104","y":1985,"id":"1985/84-5786","sc":1,"sum":"The voluntariness of a confession is not an issue of fact entitled to the §2254(d) presumption but is a legal question meriting independent consideration in a federal habeas corpus proceeding.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"22-23"}},{"t":"case","label":"Moseley v. V Secret Catalogue, Inc.","cite":"537 U.S. 418","y":2003,"id":"2002/01-1015","sc":1,"sum":"Justice John Paul Stevens delivered the opinion for a unanimous Court with respect to parts I, II, and IV of the opinion, which held that the FTDA requires proof of actual dilution.","sumSrc":"Oyez","by":{"2":"5"}},{"t":"case","label":"Mullin v. Doe","cite":"609 U.S. 324","y":2026,"id":"2025/25-1083","sc":1,"sum":"Section 1254a(b)(5)(A) bars judicial review of non-constitutional claims related to Temporary Protected Status (TPS); Miot respondents’ equal protection claim—that Haiti’s TPS designation was terminated because of race—is unlikely to succeed because a race-neutral explanation for the Government’s action exists: the current administration opposes the TPS program as it has been implemented in the past and has terminated every TPS designation that has come up for renewal.","sumSrc":"Holding (supremecourt.gov)","by":{"2":"46"}},{"t":"case","label":"Nat’l Presto Indus., Inc. v. U.S. Merchs. Fin. Grp., Inc.","cite":"121 F.4th 671","y":2024,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.4th/121/671/","sum":"Noting “the Lanham Act provides no statutory right to a jury trial” for trademarkinfringement claim.","sumSrc":"brief:2","by":{"2":"50"}},{"t":"case","label":"Naterra Int’l, Inc. v. Bensalem","cite":"92 F.4th 1113","y":2024,"court":"Fed. Cir.","url":"https://www.courtlistener.com/c/F.4th/92/1113/","by":{"2":"50"}},{"t":"case","label":"Network Automation, Inc. v. Advanced Sys. Concepts, Inc.","cite":"638 F.3d 1137","y":2011,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/638/1137/","by":{"2":"8"}},{"t":"case","label":"Park ‘N Fly, Inc. v. Dollar Park & Fly, Inc.","cite":"469 U.S. 189","y":1985,"id":"1984/83-1132","sc":1,"sum":"The holder of a registered mark may rely on incontestability to enjoin infringement, and an infringement action may not be defended on the grounds that the mark is merely descriptive.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"6"}},{"t":"case","label":"Perini Corp. v. Perini Constr., Inc.","cite":"915 F.2d 121","y":1990,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.2d/915/121/","by":{"2":"7"}},{"t":"case","label":"Progressive Distrib. Servs., Inc. v. United Parcel Serv., Inc.","cite":"856 F.3d 416","y":2017,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/856/416/","by":{"2":"50"}},{"t":"case","label":"Qualitex Co. v. Jacobson Prods. Co.","cite":"514 U.S. 159","y":1995,"id":"1994/93-1577","sc":1,"sum":"The Lanham Act permits the registration of a trademark that consists, purely and simply, of a color.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"33"}},{"t":"case","label":"Reiter v. Sonotone Corp.","cite":"442 U.S. 330","y":1979,"id":"1978/78-690","sc":1,"sum":"Consumers who pay a higher price for goods purchased for personal use as a result of antitrust violations sustain an injury in their \"property\" within the meaning of § 4.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"43"}},{"t":"case","label":"Royal Canin U.S.A., Inc. v. Wullschleger","cite":"604 U.S. 22","y":2025,"id":"2024/23-677","sc":1,"sum":"When a plaintiff amends her complaint to delete the federal-law claims that enabled removal to federal court, leaving only state-law claims behind, the federal court loses supplemental jurisdiction over the state claims, and the case must be remanded to state court.","sumSrc":"Holding (supremecourt.gov)","by":{"2":"49"}},{"t":"case","label":"SAP Am., Inc. v. InvestPic, LLC","cite":"898 F.3d 1161","y":2018,"court":"Fed. Cir.","url":"https://www.courtlistener.com/c/F.3d/898/1161/","by":{"2":"28"}},{"t":"case","label":"Sara Lee Corp. v. Kayser-Roth Corp.","cite":"81 F.3d 455","y":1996,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/81/455/","by":{"2":"48"}},{"t":"case","label":"SAS Inst., Inc. v. World Programming Ltd.","cite":"64 F.4th 1319","y":2023,"court":"Fed. Cir.","url":"https://www.courtlistener.com/c/F.4th/64/1319/","by":{"2":"28"}},{"t":"case","label":"Standard Paint Co. v. Trinidad Asphalt Mfg. Co.","cite":"220 U.S. 446","y":1911,"id":"scdb/1910-115","sc":1,"sum":"No sign or form of words can be appropriated as a valid trade-mark which, from the nature of the fact conveyed by its primary meaning, others may employ with equal right for the same purpose. Elgin National Watch Co. v. Illinois Watch Co., 179 U. S. 665.","sumSrc":"Headnote (U.S. Reports)","by":{"2":"48"}},{"t":"case","label":"Teva Pharms. USA, Inc. v. Sandoz, Inc.","cite":"574 U.S. 318","y":2015,"id":"2014/13-854","sc":1,"sum":"The Court ruled that a federal appellate court can only overturn a district court’s finding of fact if those findings were determined to be “clearly erroneous.”","sumSrc":"Oyez","by":{"2":"24-25, 27"}},{"t":"case","label":"Thompson v. Keohane","cite":"516 U.S. 99","y":1995,"id":"1995/94-6615","sc":1,"sum":"State-court \"in custody\" rulings, made to determine whether Mirandawarnings are due, do not qualify for a presumption of correctness under §2254(d). Such rulings do not resolve \"a factual issue.\" Instead, they resolve mixed questions of law and fact and therefore warrant independent review by the federal habeas court.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"46"}},{"t":"case","label":"Top Brand LLC v. Cozy Comfort Co.","cite":"143 F.4th 1349","y":2025,"court":"Fed. Cir.","url":"https://www.courtlistener.com/c/F.4th/143/1349/","by":{"2":"8"}},{"t":"case","label":"Ty Inc. v. Softbelly’s Inc.","cite":"353 F.3d 528","y":2003,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/353/528/","sum":"Noting the “fateful step” of deeming a mark generic.","sumSrc":"brief:2","by":{"2":"44"}},{"t":"case","label":"U.S. Patent & Trademark Office v. Booking.com B.V.","cite":"591 U.S. 549","y":2020,"id":"2019/19-46","sc":1,"sum":"The Court held that the addition by an online business of a generic top-level domain (“.com”) to an otherwise generic term can create a protectable trademark if the composite term is distinct from the generic term to consumers.","sumSrc":"Oyez","by":{"2":"5-6, 23, 33-34, 36-38, 43"}},{"t":"case","label":"United States v. Apel","cite":"571 U.S. 359","y":2014,"id":"2013/12-1038","sc":1,"sum":"The Court ruled that a federal statute can be enforced on a portion of military land that is subject to a public roadway easement.","sumSrc":"Oyez","by":{"2":"40"}},{"t":"case","label":"USPS v. Konan","cite":"607 U.S. 391","y":2026,"id":"2025/24-351","sc":1,"sum":"The United States retains sovereign immunity for claims arising out of the intentional nondelivery of mail because both “miscarriage” and “loss” of mail under the Federal Tort Claims Act’s postal exception, 28 U. S. C. §2680(b), can occur as a result of the Postal Service’s intentional failure to deliver the mail.","sumSrc":"Holding (supremecourt.gov)","by":{"2":"46"}},{"t":"case","label":"W.W.W. Pharm. Co., Inc. v. Gillette Co.","cite":"984 F.2d 567","y":1993,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.2d/984/567/","by":{"2":"35"}},{"t":"case","label":"Warner Chappell Music, Inc. v. Nealy","cite":"601 U.S. 366","y":2024,"id":"2023/22-1078","sc":1,"sum":"The Copyright Act entitles a copyright owner to obtain monetary relief for any timely infringement claim, no matter when the infringement occurred.","sumSrc":"Holding (supremecourt.gov)","by":{"2":"50"}},{"t":"case","label":"Water Pik, Inc. v. Med-Sys., Inc.","cite":"726 F.3d 1136","y":2013,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/726/1136/","by":{"2":"8"}},{"t":"case","label":"Yuga Labs, Inc. v. Ripps","cite":"144 F.4th 1137","y":2025,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.4th/144/1137/","sum":"Holding that marks, “[f]ar from describing [the products], … are arbitrary, if not entirely fanciful”.","sumSrc":"brief:2","by":{"2":"48"}},{"t":"const","label":"Amendment I","clauses":[["establishment","Establishment Clause"],["free-exercise","Free Exercise Clause"],["free-speech","Free Speech Clause"],["free-press","Free Press Clause"],["assembly-petition","Assembly, Petition and Association"]],"text":"Congress shall make no law respecting an establishment of religion, or prohibiting the free exercise thereof; or abridging the freedom of speech, or of the press; or the right of the people peaceably to assemble, and to petition the Government for a redress of grievances.","by":{"2":"2, 19, 26, 47"}}]};